def prefix(typ, name):
    if typ == "int?":
        return "int" + name
    if typ == "long?":
        return "lng" + name
    if typ == "byte?":
        return "byt" + name
    if typ == "string":
        return "str" + name
    if typ == "bool":
        return "bol" + name
    if typ == "DateTime?":
        return "dtm" + name
    raise Exception(typ)

def default_val(typ):
    if typ == "bool":
        return "false"
    return "null"

def convert_fn(typ):
    if typ == "int?":
        return "Convert.ToInt32"
    if typ == "long?":
        return "Convert.ToInt64"
    if typ == "byte?":
        return "Convert.ToByte"
    if typ == "string":
        return "Convert.ToString"
    if typ == "bool":
        return "Convert.ToBoolean"
    if typ == "DateTime?":
        return "Convert.ToDateTime"
    raise Exception(typ)

