function prefix(typ, name) {
  if (typ === "int?") return "int" + name;
  if (typ === "long?") return "lng" + name;
  if (typ === "byte?") return "byt" + name;
  if (typ === "string") return "str" + name;
  if (typ === "bool") return "bol" + name;
  if (typ === "DateTime?") return "dtm" + name;
  throw new Error(typ);
}
function defaultVal(typ) { return typ === "bool" ? "false" : "null"; }
function convertFn(typ) {
  return {
    "int?": "Convert.ToInt32",
    "long?": "Convert.ToInt64",
    "byte?": "Convert.ToByte",
    "string": "Convert.ToString",
    "bool": "Convert.ToBoolean",
    "DateTime?": "Convert.ToDateTime"
  }[typ];
}

