CREATE PROCEDURE [dbo].[POL_NEW_Survey_GETALL]
AS
BEGIN
    SELECT
        [SurveyID],
        [SurveyCode],
        [SurveyName],
        [Brief],
        [VersionNo],
        [IsActived],
        [OrderIndex]
    From [POL_NEW_Survey]
    Where [IsActived] = 1
    Order By [OrderIndex], [SurveyID]
END
GO

CREATE PROCEDURE [dbo].[POL_NEW_Plan_SEARCH]
(
    @Keyword nvarchar(500) = null
)
AS
BEGIN
    If isnull(@Keyword, '') = '' Set @Keyword = null
    Else Set @Keyword = '%' + @Keyword + '%'

    SELECT
        tbl.*,
        tblSurvey.SurveyCode,
        tblSurvey.SurveyName,
        tblSurvey.SurveyCode AS PollCode,
        tblSurvey.SurveyName AS PollName
    From POL_NEW_Plan tbl
        Inner Join POL_NEW_Survey tblSurvey On tblSurvey.SurveyID = tbl.SurveyID
    Where tbl.PlanID > 0
        And (
            @Keyword is null
            Or tbl.PlanCode Like @Keyword
            Or tbl.PlanName Like @Keyword
            Or tbl.Description Like @Keyword
            Or tblSurvey.SurveyCode Like @Keyword
            Or tblSurvey.SurveyName Like @Keyword
        )
    Order By tbl.YearID, tbl.Semester, tbl.OrderIndex, tbl.PlanID
END
GO

CREATE PROCEDURE [dbo].[POL_NEW_Plan_ADD]
(
    @PlanCode nvarchar(50) = null,
    @PlanName nvarchar(250) = null,
    @SurveyID int = 0,
    @YearID int,
    @Semester int = null,
    @PlanBrief nvarchar(1000) = null,
    @PlanContent ntext = null,
    @StartDate datetime = null,
    @FinishDate datetime = null,
    @IsStudentOfCourse bit = 0,
    @IsAllStudent bit = 0,
    @IsAllTeacher bit = 0,
    @IsAllEmployee bit = 0,
    @IsAllUser bit = 0,
    @IsCompanyList bit = 0,
    @IsPublic bit = 0,
    @IsActived bit = 1,
    @OrderIndex int = null,
    @Description nvarchar(500) = null,
    @CreatedUser nvarchar(50) = N'administrator'
)
AS
BEGIN
    SET NOCOUNT OFF

    INSERT INTO [POL_NEW_Plan]
    (
        [PlanCode],
        [PlanName],
        [SurveyID],
        [YearID],
        [Semester],
        [PlanBrief],
        [PlanContent],
        [StartDate],
        [FinishDate],
        [IsStudentOfCourse],
        [IsAllStudent],
        [IsAllTeacher],
        [IsAllEmployee],
        [IsAllUser],
        [IsCompanyList],
        [IsPublic],
        [IsActived],
        [OrderIndex],
        [Description],
        [CreatedUser]
    )
    VALUES
    (
        @PlanCode,
        @PlanName,
        @SurveyID,
        @YearID,
        @Semester,
        @PlanBrief,
        @PlanContent,
        @StartDate,
        @FinishDate,
        @IsStudentOfCourse,
        @IsAllStudent,
        @IsAllTeacher,
        @IsAllEmployee,
        @IsAllUser,
        @IsCompanyList,
        @IsPublic,
        @IsActived,
        @OrderIndex,
        @Description,
        @CreatedUser
    )

    SELECT SCOPE_IDENTITY()
END
GO

