    @Description nvarchar(500) = null,
    @UpdatedUser nvarchar(50) = null
)
AS
BEGIN
    SET NOCOUNT OFF

    UPDATE [POL_NEW_Plan]
    SET
        [PlanCode] = @PlanCode,
        [PlanName] = @PlanName,
        [SurveyID] = @SurveyID,
        [YearID] = @YearID,
        [Semester] = @Semester,
        [PlanBrief] = @PlanBrief,
        [PlanContent] = @PlanContent,
        [StartDate] = @StartDate,
        [FinishDate] = @FinishDate,
        [IsStudentOfCourse] = @IsStudentOfCourse,
        [IsAllStudent] = @IsAllStudent,
        [IsAllTeacher] = @IsAllTeacher,
        [IsAllEmployee] = @IsAllEmployee,
        [IsAllUser] = @IsAllUser,
        [IsCompanyList] = @IsCompanyList,
        [IsPublic] = @IsPublic,
        [IsActived] = @IsActived,
        [OrderIndex] = @OrderIndex,
        [Description] = @Description,
        [UpdatedDate] = GETDATE(),
        [UpdatedUser] = @UpdatedUser
    Where [PlanID] = @PlanID
END
GO

CREATE PROCEDURE [dbo].[POL_NEW_Plan_DELETE]
(
    @PlanID int
)
AS
BEGIN
    If exists (Select Top 1 PlanID From POL_NEW_Response Where PlanID = @PlanID And IsDeleted = 0)
    Begin
        Raiserror (N'Đã tồn tại phiếu khảo sát ở kế hoạch này!', 16, 1)
        Return
    End

    Delete POL_NEW_ResponseDetail
    From POL_NEW_ResponseDetail
        Inner Join POL_NEW_Response On POL_NEW_Response.ResponseID = POL_NEW_ResponseDetail.ResponseID
            And POL_NEW_Response.PlanID = @PlanID
            And POL_NEW_Response.IsDeleted = 1

    Delete POL_NEW_Response
    Where PlanID = @PlanID And IsDeleted = 1

    Delete POL_NEW_Plan_Course
    Where [PlanID] = @PlanID

    Delete POL_NEW_Plan
    Where [PlanID] = @PlanID
END
GO

CREATE PROCEDURE [dbo].[POL_NEW_Plan_Course_SearchForPlan]
(
    @PlanID bigint = null
)
AS
BEGIN
    Select *
    Into #tblData
    From POL_NEW_Plan_Course
    Where PlanID = @PlanID

    SELECT
        tbl.*,
        SIM_Course.CourseName,
        SIM_Course.StartYear,
        SIM_Course.FinishYear,
        tbl.PlanCourseID AS PlanCourseIDTemp,
        0 AS IsEdit,
        0 AS IsDeleted
    From #tblData tbl
        Inner Join SIM_Course On SIM_Course.CourseID = tbl.CourseID
    Order By SIM_Course.StartYear DESC, SIM_Course.CourseID
END
GO

